import React from 'react';
import { Link } from 'react-router-dom';

function Home() {
  return (
    <div className="container py-5">
      <div className="row justify-content-center">
        <div className="col-md-8 text-center">
          <h1 className="mb-4">Bienvenido al Sistema de Gestión de Usuarios</h1>
          <p className="lead mb-4">Accede a tus aplicaciones y gestiona tu perfil de usuario.</p>
          <Link to="/login" className="btn btn-primary btn-lg">Iniciar sesión</Link>
        </div>
      </div>
    </div>
  );
}

export default Home;
